import {readFileSync,writeFileSync} from 'node:fs';
const files=['20261028_switch_pilot.sql','20261029_switch_launch_evidence.sql'];
const body=files.map(name=>'-- Source: '+name+'\n'+readFileSync(new URL('../supabase/migrations/'+name,import.meta.url),'utf8').replace(/^begin;\s*$/gmi,'').replace(/^commit;\s*$/gmi,'').trim()).join('\n\n');
const output='-- GENERATED by scripts/switch-migration-bundle.mjs; review before applying.\n-- Existing M Select project only. No new database; no production execution without permission.\nbegin;\nset local lock_timeout = \'3s\';\nset local statement_timeout = \'30s\';\n\n'+body+'\n\ncommit;\n';
const target=new URL('../docs/sql/ATIVAR-M-SWITCH.sql',import.meta.url);
if(process.argv.includes('--write'))writeFileSync(target,output);
else if(readFileSync(target,'utf8').replace(/\r\n/g,'\n')!==output.replace(/\r\n/g,'\n'))throw Error('M Switch SQL bundle is stale. Run node scripts/switch-migration-bundle.mjs --write');
console.log('M Switch SQL bundle verified; no database connection made.');
